void collectNames(List<Order> orders, Collection<String> out) {
    for (Order o : orders) out.add(o.customerName());   // append to caller's collection
}

List<String> names = new ArrayList<>();
collectNames(orders, names);
StringBuilder sb = new StringBuilder();
for (String n : names) sb.append(n).append(';');

// The accumulator contract is passed to the pipeline:
List<String> names = orders.stream()
    .map(Order::customerName)
    .collect(Collectors.toList());

// Same shape spelled out (supplier / accumulator / combiner):
StringBuilder sb = orders.stream().collect(
    StringBuilder::new,
    (acc, o) -> acc.append(o.customerName()).append(';'),
    StringBuilder::append);

